() => {
  // Find the echarts container (usually a div with _echarts_instance_ attribute or canvas/svg)
  const charts = Array.from(document.querySelectorAll('div[_echarts_instance_]'));
  if (charts.length) {
    const el = charts[charts.length - 1];
    el.scrollIntoView({block: 'center', behavior: 'instant'});
    const r = el.getBoundingClientRect();
    return JSON.stringify({found: 'echarts', x: r.x, y: r.y, w: r.width, h: r.height});
  }
  // fallback: find svg chart
  const svgs = Array.from(document.querySelectorAll('main svg'));
  if (svgs.length) {
    const el = svgs[svgs.length - 1];
    el.scrollIntoView({block: 'center', behavior: 'instant'});
    const r = el.getBoundingClientRect();
    return JSON.stringify({found: 'svg', x: r.x, y: r.y, w: r.width, h: r.height});
  }
  return 'no chart found';
}

() => {
  const headings = Array.from(document.querySelectorAll('h4'));
  const h = headings.find(el => el.textContent.includes('各客户类型数量分布'));
  if (!h) return 'no heading';
  // Walk up to find a container, then list its descendant svg/canvas sizes
  let container = h.parentElement;
  for (let i = 0; i < 6 && container; i++) {
    const svgs = container.querySelectorAll('svg');
    const canvases = container.querySelectorAll('canvas');
    const bigSvg = Array.from(svgs).find(s => s.getBoundingClientRect().width > 100);
    if (bigSvg || canvases.length) {
      const el = bigSvg || canvases[0];
      const r = el.getBoundingClientRect();
      return JSON.stringify({level: i, tag: el.tagName, x: r.x, y: r.y, w: r.width, h: r.height, containerClass: container.className});
    }
    container = container.parentElement;
  }
  // fallback: list all svgs with size > 100
  const all = Array.from(document.querySelectorAll('svg')).map(s => { const r = s.getBoundingClientRect(); return {w: r.width, h: r.height, x: r.x, y: r.y}; }).filter(o => o.w > 100);
  return JSON.stringify({bigSvgs: all});
}

() => {
  const headings = Array.from(document.querySelectorAll('h4'));
  const h = headings.find(el => el.textContent.includes('各客户类型数量分布'));
  let container = h.parentElement.parentElement;
  const svg = Array.from(container.querySelectorAll('svg')).find(s => s.getBoundingClientRect().width > 100);
  if (!svg) return 'no svg';
  // Identify chart library
  let lib = 'unknown';
  let node = svg;
  for (let i = 0; i < 8 && node; i++) {
    const cls = (node.className && node.className.baseVal !== undefined) ? node.className.baseVal : (node.className || '');
    if (typeof cls === 'string') {
      if (cls.includes('recharts')) { lib = 'recharts'; break; }
      if (cls.includes('echarts')) { lib = 'echarts'; break; }
      if (cls.includes('visx') || cls.includes('vx-')) { lib = 'visx'; break; }
    }
    node = node.parentElement;
  }
  // List path elements (sectors) with bounding boxes
  const paths = Array.from(svg.querySelectorAll('path')).map((p, i) => {
    const r = p.getBoundingClientRect();
    const cls = p.getAttribute('class') || '';
    const name = p.getAttribute('name') || '';
    return {i, x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), cls: cls.slice(0, 80), name};
  }).filter(o => o.w > 5 && o.h > 5);
  return JSON.stringify({lib, svgRect: svg.getBoundingClientRect(), pathCount: paths.length, paths: paths.slice(0, 20)});
}

() => {
  const svgs = Array.from(document.querySelectorAll('svg')).map((s, i) => {
    const r = s.getBoundingClientRect();
    let cls = '';
    try { cls = typeof s.className === 'string' ? s.className : (s.className.baseVal || ''); } catch(e) {}
    let parentCls = s.parentElement ? (s.parentElement.className || '') : '';
    return {i, x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), cls: String(cls).slice(0,60), parentCls: String(parentCls).slice(0,60)};
  }).filter(o => o.w > 50 && o.h > 50);
  const canvases = Array.from(document.querySelectorAll('canvas')).map((c, i) => {
    const r = c.getBoundingClientRect();
    return {i, x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height)};
  });
  return JSON.stringify({bigSvgs: svgs, canvases});
}

() => {
  const wrapper = document.querySelector('.recharts-wrapper');
  if (!wrapper) return 'no wrapper';
  wrapper.scrollIntoView({block: 'center', behavior: 'instant'});
  const sectors = Array.from(document.querySelectorAll('.recharts-pie-sector path, g.recharts-layer.recharts-pie-sector path'));
  const info = sectors.map((p, i) => {
    const r = p.getBoundingClientRect();
    return {i, cx: Math.round(r.x + r.width/2), cy: Math.round(r.y + r.height/2), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), fill: p.getAttribute('fill'), name: p.getAttribute('name')};
  });
  // also check for any sector-like paths
  const allPaths = Array.from(document.querySelectorAll('.recharts-wrapper path')).map((p, i) => {
    const r = p.getBoundingClientRect();
    return {i, cls: (p.parentElement.getAttribute('class')||'').slice(0,50), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height)};
  }).filter(o => o.w > 10);
  return JSON.stringify({sectorCount: sectors.length, sectors: info, wrapperRect: wrapper.getBoundingClientRect(), allPathsCount: allPaths.length, allPaths: allPaths.slice(0,15)});
}

() => {
  const sectorG = Array.from(document.querySelectorAll('g.recharts-pie-sector'));
  const paths = sectorG.map(g => g.querySelector('path')).filter(Boolean);
  const target = paths.find(p => p.getAttribute('name') === '产业客户');
  if (!target) return 'no target 产业客户';
  const r = target.getBoundingClientRect();
  const cx = r.x + r.width / 2, cy = r.y + r.height / 2;
  const targetG = target.closest('g.recharts-pie-sector');
  let hit = null;
  outer:
  for (const rad of [55, 65, 45, 75, 35]) {
    for (let a = 0; a < 360; a += 2) {
      const x = cx + rad * Math.cos(a * Math.PI / 180);
      const y = cy + rad * Math.sin(a * Math.PI / 180);
      const el = document.elementFromPoint(x, y);
      if (el && (el === target || (el.closest && el.closest('g.recharts-pie-sector') === targetG))) {
        hit = {x: Math.round(x), y: Math.round(y), angle: a, rad};
        break outer;
      }
    }
  }
  if (!hit) return 'no hit point';
  const opts = {bubbles: true, cancelable: true, composed: true, view: window, clientX: hit.x, clientY: hit.y, screenX: hit.x, screenY: hit.y};
  target.dispatchEvent(new MouseEvent('mouseover', opts));
  target.dispatchEvent(new MouseEvent('mousemove', opts));
  targetG.dispatchEvent(new MouseEvent('mouseover', opts));
  targetG.dispatchEvent(new MouseEvent('mousemove', opts));
  return JSON.stringify({hit, center: {cx: Math.round(cx), cy: Math.round(cy)}});
}

() => new Promise(resolve => {
  setTimeout(() => {
    const tips = Array.from(document.querySelectorAll('.recharts-tooltip-wrapper'));
    const visible = tips.filter(t => {
      const style = window.getComputedStyle(t);
      return style.visibility !== 'hidden' && style.display !== 'none' && t.textContent.trim().length > 0;
    }).map(t => {
      const r = t.getBoundingClientRect();
      return {text: t.textContent, html: t.innerHTML.slice(0, 600), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), visibility: window.getComputedStyle(t).visibility};
    });
    resolve(JSON.stringify({tooltipCount: tips.length, visible}));
  }, 800);
})

() => {
  const paths = Array.from(document.querySelectorAll('g.recharts-pie-sector path'));
  const target = paths.find(p => p.getAttribute('name') === '产业客户');
  if (!target) return 'no target';
  const r = target.getBoundingClientRect();
  const cx = r.x + r.width / 2, cy = r.y + r.height / 2;
  // hover on left side of pie (angle 180) so tooltip shifts left into viewport
  const x = cx - 55, y = cy;
  const opts = {bubbles: true, cancelable: true, composed: true, view: window, clientX: x, clientY: y, screenX: x, screenY: y};
  target.dispatchEvent(new MouseEvent('mouseout', opts));
  target.dispatchEvent(new MouseEvent('mouseover', opts));
  target.dispatchEvent(new MouseEvent('mousemove', opts));
  return JSON.stringify({hover: {x, y}, el: document.elementFromPoint(x, y) ? document.elementFromPoint(x, y).tagName : 'none'});
}

