() => {
  document.body.style.zoom = '1';
  const tip = document.querySelector('.recharts-tooltip-wrapper');
  if (!tip) return 'no tip';
  const before = tip.getBoundingClientRect();
  // shift tooltip left so it is fully visible in the narrow viewport
  tip.style.transition = 'none';
  const r = tip.getBoundingClientRect();
  const shiftX = Math.max(0, (r.x + r.width) - 470);
  const cur = tip.style.transform || '';
  tip.style.transform = `translate(${-shiftX - 10}px, 0px) ` + cur;
  const after = tip.getBoundingClientRect();
  return JSON.stringify({before: {x: Math.round(before.x), w: Math.round(before.width)}, shiftX, after: {x: Math.round(after.x), y: Math.round(after.y), w: Math.round(after.width)}, text: tip.textContent, vis: window.getComputedStyle(tip).visibility});
}

() => {
  const paths = Array.from(document.querySelectorAll('g.recharts-pie-sector path'));
  const all = paths.map(p => ({name: p.getAttribute('name'), fill: p.getAttribute('fill')}));
  const target = paths.find(p => p.getAttribute('name') === '地方政府');
  if (!target) return JSON.stringify({err: 'no 地方政府', all});
  // pie center from largest sector bbox
  const big = paths.find(p => p.getAttribute('name') === '产业客户');
  const rb = big.getBoundingClientRect();
  const cx = rb.x + rb.width / 2, cy = rb.y + rb.height / 2;
  const targetG = target.closest('g.recharts-pie-sector');
  let hit = null;
  outer:
  for (const rad of [60, 70, 50, 80]) {
    for (let a = 0; a < 360; a += 1) {
      const x = cx + rad * Math.cos(a * Math.PI / 180);
      const y = cy + rad * Math.sin(a * Math.PI / 180);
      const el = document.elementFromPoint(x, y);
      if (el && (el === target || (el.closest && el.closest('g.recharts-pie-sector') === targetG))) {
        hit = {x, y, angle: a, rad};
        break outer;
      }
    }
  }
  if (!hit) return 'no hit for 地方政府';
  const opts = {bubbles: true, cancelable: true, composed: true, view: window, clientX: hit.x, clientY: hit.y, screenX: hit.x, screenY: hit.y};
  target.dispatchEvent(new MouseEvent('mouseover', opts));
  target.dispatchEvent(new MouseEvent('mousemove', opts));
  return JSON.stringify({hit, sectors: all});
}

() => new Promise(resolve => {
  setTimeout(() => {
    const tip = document.querySelector('.recharts-tooltip-wrapper');
    if (!tip) return resolve('no tooltip');
    const r = tip.getBoundingClientRect();
    // shift left if clipped
    const overflow = (r.x + r.width) - 470;
    if (overflow > 0) {
      tip.style.transition = 'none';
      tip.style.transform = (tip.style.transform || '') + ` translate(${-overflow - 10}px, 0px)`;
    }
    const r2 = tip.getBoundingClientRect();
    resolve(JSON.stringify({text: tip.textContent, html: tip.innerHTML.slice(0,700), before: {x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width)}, after: {x: Math.round(r2.x), y: Math.round(r2.y)}, vis: window.getComputedStyle(tip).visibility}));
  }, 700);
})

