() => {
  const bars = Array.from(document.querySelectorAll('g.recharts-bar-rectangle path'));
  if (!bars.length) return 'no bars';
  const bar = bars[0]; // 产业客户 tallest bar
  const r = bar.getBoundingClientRect();
  const x = r.x + r.width / 2, y = r.y + r.height / 2;
  const opts = {bubbles: true, cancelable: true, composed: true, view: window, clientX: x, clientY: y, screenX: x, screenY: y};
  bar.dispatchEvent(new MouseEvent('mouseover', opts));
  bar.dispatchEvent(new MouseEvent('mousemove', opts));
  const barG = bar.closest('g.recharts-bar-rectangle');
  if (barG) {
    barG.dispatchEvent(new MouseEvent('mouseover', opts));
    barG.dispatchEvent(new MouseEvent('mousemove', opts));
  }
  return JSON.stringify({hover: {x: Math.round(x), y: Math.round(y)}, el: (document.elementFromPoint(x, y) || {}).tagName});
}

() => new Promise(resolve => {
  setTimeout(() => {
    const tip = document.querySelector('.recharts-tooltip-wrapper');
    if (!tip) return resolve('no tooltip');
    const r = tip.getBoundingClientRect();
    const vis = window.getComputedStyle(tip).visibility;
    // shift into viewport if needed
    let shifted = 0;
    if (r.x + r.width > 470) {
      shifted = (r.x + r.width) - 470 + 10;
      tip.style.transition = 'none';
      tip.style.transform = (tip.style.transform || '') + ` translate(${-shifted}px, 0px)`;
    }
    const r2 = tip.getBoundingClientRect();
    resolve(JSON.stringify({text: tip.textContent, html: tip.innerHTML.slice(0, 700), vis, before: {x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width)}, after: {x: Math.round(r2.x), y: Math.round(r2.y)}}));
  }, 700);
})

