() => {
  const svg = document.querySelector('.recharts-wrapper svg.recharts-surface');
  const bars = Array.from(document.querySelectorAll('g.recharts-bar-rectangle path'));
  if (!svg || bars.length < 2) return 'missing';
  const r = bars[1].getBoundingClientRect();
  const x = r.x + r.width / 2, y = r.y + r.height / 2;
  const opts = {bubbles: true, cancelable: true, composed: true, view: window, clientX: x, clientY: y, screenX: x, screenY: y};
  // move on surface (categorical tooltip computes index from coordinate)
  svg.dispatchEvent(new MouseEvent('mousemove', opts));
  bars[1].dispatchEvent(new MouseEvent('mousemove', opts));
  return new Promise(resolve => setTimeout(() => {
    const tip = document.querySelector('.recharts-tooltip-wrapper');
    if (!tip) return resolve('no tooltip');
    const tr = tip.getBoundingClientRect();
    if (tr.x + tr.width > 470) {
      const shift = (tr.x + tr.width) - 470 + 10;
      tip.style.transition = 'none';
      tip.style.transform = (tip.style.transform || '') + ` translate(${-shift}px, 0px)`;
    }
    const tr2 = tip.getBoundingClientRect();
    resolve(JSON.stringify({text: tip.textContent, vis: window.getComputedStyle(tip).visibility, rect: {x: Math.round(tr2.x), y: Math.round(tr2.y)}, hitEl: (document.elementFromPoint(x, y) || {}).tagName, hoverPoint: {x: Math.round(x), y: Math.round(y)}}));
  }, 700));
}

